import React from 'react';
import { Task } from '../../../../models/Task';
import { Badge } from '../../../../components/common/Badge';
import styles from './TaskInfoCard.module.css';

export interface TaskInfoCardProps {
  task: Task;
}

export const TaskInfoCard: React.FC<TaskInfoCardProps> = ({ task }) => {
  return (
    <div className={styles.card}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>
          <i className="fas fa-info-circle"></i> Thông Tin Task
        </h3>
      </div>
      <div className={styles.cardBody}>
        <div className={styles.taskInfo}>
          <div>
            <label className={styles.fieldLabel}>Tiêu đề</label>
            <div className={styles.taskTitle}>{task.title}</div>
          </div>

          <div>
            <label className={styles.fieldLabel}>Mô tả</label>
            <div className={styles.taskDescription}>{task.description}</div>
          </div>

          <div className={styles.infoGrid}>
            <div>
              <label className={styles.fieldLabel}>Danh mục</label>
              <div>
                {task.category ? (
                  <Badge variant="info">
                    <i className="fas fa-folder"></i> {task.category}
                  </Badge>
                ) : (
                  <span className={styles.infoValue}>N/A</span>
                )}
              </div>
            </div>
            <div>
              <label className={styles.fieldLabel}>Phòng ban</label>
              <div>
                {task.departmentName ? (
                  <Badge variant="secondary">
                    <i className="fas fa-building"></i> {task.departmentName}
                  </Badge>
                ) : (
                  <span className={styles.infoValue}>N/A</span>
                )}
              </div>
            </div>
          </div>

          {task.tags && task.tags.length > 0 && (
            <div>
              <label className={styles.fieldLabel}>Tags</label>
              <div className={styles.tagsList}>
                {task.tags.map((tag, index) => (
                  <span key={index} className={styles.tag}>
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
