import type { Ticket, TicketFilters } from '../../models/Ticket';
import type { PaginatedResponse } from '../../models/common';
import { ticketEndpoint } from './endpoint';

/**
 * Unified ticket service.
 *
 * Endpoint reference: web-bff/api/v1/tickets
 */
export const ticketService = {
  // ── Read ───────────────────────────────────────────────────────────────────

  getTickets: (filters?: TicketFilters, page = 1, pageSize = 20): Promise<PaginatedResponse<Ticket>> =>
    ticketEndpoint.getTickets({
      page, pageSize,
      priority:     filters?.priority,
      status:       filters?.status,
      departmentId: filters?.departmentId,
      assigneeId:   filters?.assigneeId,
      slaStatus:    filters?.slaStatus,
      search:       filters?.search,
    }),

  getTicketById: (id: string): Promise<Ticket> => ticketEndpoint.getTicketById(id),

  // ── Write ──────────────────────────────────────────────────────────────────

  createTicket: (data: Partial<Ticket>): Promise<Ticket> =>
    ticketEndpoint.createTicket({
      title:          data.title ?? '',
      description:    data.description ?? '',
      priority:       data.priority ?? '',
      category:       data.category,
      departmentId:   data.departmentId || undefined,
      departmentName: data.departmentName || undefined,
      dueDate:        data.dueDate ? new Date(data.dueDate).toISOString() : undefined,
      tags:           data.tags,
    }),

  updateTicket: (id: string, data: Partial<Ticket>): Promise<Ticket> =>
    ticketEndpoint.updateTicket(id, {
      title:        data.title,
      description:  data.description,
      priority:     data.priority,
      category:     data.category,
      departmentId: data.departmentId || undefined,
      dueDate:      data.dueDate ? new Date(data.dueDate).toISOString() : undefined,
      tags:         data.tags,
    }),

  deleteTicket: (id: string): Promise<void> => ticketEndpoint.deleteTicket(id),

  // ── Assignment ─────────────────────────────────────────────────────────────

  assignTicket: (ticketId: string, assigneeId: string, assigneeName = ''): Promise<Ticket> =>
    ticketEndpoint.assignTicket(ticketId, { assigneeId, assigneeName }),

  // ── Triage ─────────────────────────────────────────────────────────────────

  /**
   * @deprecated Use acceptTicket / rejectTicket / pendingTicket directly.
   * Kept for backwards compatibility with existing thunks.
   */
  triageTicket: (
    ticketId: string,
    action: 'accept' | 'reject' | 'request_info',
    priority?: string,
    reason?: string
  ): Promise<Ticket> => {
    switch (action) {
      case 'accept':
        return ticketService.acceptTicket(ticketId, priority, reason);
      case 'reject':
        return ticketService.rejectTicket(ticketId, reason ?? '');
      case 'request_info':
        return ticketService.pendingTicket(ticketId, reason ?? '');
      default:
        return Promise.reject(new Error(`Invalid triage action: ${action}`));
    }
  },

  acceptTicket: (ticketId: string, priority?: string, note?: string): Promise<Ticket> =>
    ticketEndpoint.acceptTicket(ticketId, { priority, note }),

  rejectTicket: (ticketId: string, reason: string): Promise<Ticket> =>
    ticketEndpoint.rejectTicket(ticketId, { reason }),

  pendingTicket: (ticketId: string, reason: string): Promise<Ticket> =>
    ticketEndpoint.pendingTicket(ticketId, { reason }),

  // ── Progress & estimate ────────────────────────────────────────────────────

  updateProgress: (ticketId: string, percentage: number, note?: string): Promise<Ticket> =>
    ticketEndpoint.updateProgress(ticketId, { percentage, note }),

  updateEstimate: (ticketId: string, estimatedCompletionAt: Date | string, note?: string): Promise<Ticket> =>
    ticketEndpoint.updateEstimate(ticketId, {
      estimatedCompletionAt: new Date(estimatedCompletionAt).toISOString(),
      note,
    }),

  // ── Help workflow ──────────────────────────────────────────────────────────

  requestHelp: (ticketId: string, description: string, suggestedHelperId?: string): Promise<Ticket> =>
    ticketEndpoint.requestHelp(ticketId, { description, suggestedHelperId }),

  assignHelper: (ticketId: string, helperId: string, helperName = ''): Promise<Ticket> =>
    ticketEndpoint.assignSupport(ticketId, {
      helpers: [{ userId: helperId, userName: helperName }],
    }),

  assignTicketSupport: (
    ticketId: string,
    helpers: { userId: string; userName: string }[]
  ): Promise<Ticket> =>
    ticketEndpoint.assignSupport(ticketId, { helpers }),

  removeHelper: (_ticketId: string, _helperId: string): Promise<Ticket> =>
    Promise.reject(new Error('Tính năng xóa người hỗ trợ chưa được hỗ trợ trên API.')),

  // ── Status updates (generic — kept for backwards compatibility) ────────────

  /** @deprecated Use specific action endpoints instead. */
  updateStatus: (_ticketId: string, _status: string): Promise<Ticket> =>
    Promise.reject(
      new Error('updateStatus: use specific action endpoints (acceptTicket, rejectTicket, etc.) instead.')
    ),

  // ── Resolution ─────────────────────────────────────────────────────────────

  resolveTicket: (ticketId: string, resolutionNote: string): Promise<Ticket> =>
    ticketEndpoint.resolveTicket(ticketId, { resolutionNote }),

  closeTicket: (ticketId: string, note?: string): Promise<Ticket> =>
    ticketEndpoint.closeTicket(ticketId, { note }),

  reopenTicket: (ticketId: string, reason: string): Promise<Ticket> =>
    ticketEndpoint.reopenTicket(ticketId, { reason }),
};
