import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line, Doughnut } from 'react-chartjs-2';
import {
  PerformanceDataPoint,
  PriorityDistribution,
} from '../../../models/ManagerDashboard';
import styles from './PerformanceCharts.module.css';

// Register Chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

interface PerformanceChartsProps {
  performanceTrend: PerformanceDataPoint[];
  priorityDistribution: PriorityDistribution;
}

export const PerformanceCharts: React.FC<PerformanceChartsProps> = ({
  performanceTrend,
  priorityDistribution,
}) => {
  // Completion Trend Chart Data
  const completionTrendData = {
    labels: performanceTrend.map((point) => point.label),
    datasets: [
      {
        label: 'Phiếu yêu cầu',
        data: performanceTrend.map((point) => point.tickets),
        borderColor: '#2563eb',
        backgroundColor: 'rgba(37, 99, 235, 0.1)',
        tension: 0.4,
        fill: true,
      },
      {
        label: 'Công việc',
        data: performanceTrend.map((point) => point.tasks),
        borderColor: '#10b981',
        backgroundColor: 'rgba(16, 185, 129, 0.1)',
        tension: 0.4,
        fill: true,
      },
    ],
  };

  const completionTrendOptions = {
    responsive: true,
    maintainAspectRatio: true,
    plugins: {
      legend: {
        position: 'bottom' as const,
      },
      title: {
        display: false,
      },
    },
    scales: {
      y: {
        beginAtZero: true,
      },
    },
  };

  // Priority Distribution Chart Data
  const priorityDistributionData = {
    labels: ['Khẩn cấp', 'Cao', 'Trung bình', 'Thấp'],
    datasets: [
      {
        data: [
          priorityDistribution.emergency,
          priorityDistribution.high,
          priorityDistribution.medium,
          priorityDistribution.low,
        ],
        backgroundColor: ['#ef4444', '#f59e0b', '#3b82f6', '#10b981'],
        borderWidth: 0,
      },
    ],
  };

  const priorityDistributionOptions = {
    responsive: true,
    maintainAspectRatio: true,
    plugins: {
      legend: {
        position: 'bottom' as const,
      },
      title: {
        display: false,
      },
    },
  };

  return (
    <div className={styles.performanceCharts}>
      {/* Completion Trend Chart */}
      <div className={styles.chartCard}>
        <div className={styles.chartHeader}>
          <h3 className={styles.chartTitle}>
            <i className="fas fa-chart-line" /> Xu Hướng Hoàn Thành (30 ngày)
          </h3>
        </div>
        <div className={styles.chartBody}>
          <Line data={completionTrendData} options={completionTrendOptions} />
        </div>
      </div>

      {/* Priority Distribution Chart */}
      <div className={styles.chartCard}>
        <div className={styles.chartHeader}>
          <h3 className={styles.chartTitle}>
            <i className="fas fa-chart-pie" /> Phân Bổ Theo Ưu Tiên
          </h3>
        </div>
        <div className={styles.chartBody}>
          <Doughnut
            data={priorityDistributionData}
            options={priorityDistributionOptions}
          />
        </div>
      </div>
    </div>
  );
};
