import React from 'react';
import { Button } from '../../../../components/common/Button';
import styles from './ProgressCard.module.css';

interface ProgressCardProps {
  progress: number;
  onProgressChange: (value: number) => void;
  onUpdate?: () => void;
  onCancel?: () => void;
  isUpdating?: boolean;
  /** Ghi chú kèm theo khi cập nhật tiến độ */
  note?: string;
  onNoteChange?: (note: string) => void;
}

export const ProgressCard: React.FC<ProgressCardProps> = ({
  progress,
  onProgressChange,
  onUpdate,
  onCancel,
  isUpdating = false,
  note = '',
  onNoteChange,
}) => {
  const handleDecrease = () => onProgressChange(Math.max(0, progress - 5));
  const handleIncrease = () => onProgressChange(Math.min(100, progress + 5));

  return (
    <div className={styles.progressCard}>
      <div className={styles.cardBody}>
        {/* Big progress number */}
        <div className={styles.progressDisplay}>
          {progress}<span className={styles.progressUnit}>%</span>
        </div>

        {/* Slider row: [-5%] [track] [+5%] */}
        <div className={styles.sliderRow}>
          <button
            className={styles.stepBtn}
            onClick={handleDecrease}
            disabled={progress === 0 || isUpdating}
            aria-label="Giảm 5%"
          >
            -5%
          </button>

          <div className={styles.sliderWrap}>
            <input
              type="range"
              min="0"
              max="100"
              value={progress}
              onChange={(e) => onProgressChange(Number(e.target.value))}
              className={styles.progressSlider}
              style={{ '--fill': `${progress}%` } as React.CSSProperties}
              aria-label="Progress slider"
            />
          </div>

          <button
            className={styles.stepBtn}
            onClick={handleIncrease}
            disabled={progress === 100 || isUpdating}
            aria-label="Tăng 5%"
          >
            +5%
          </button>
        </div>

        {/* Track labels */}
        <div className={styles.sliderLabels}>
          <span>0%</span>
          <span>100%</span>
        </div>

        {/* Ghi chú */}
        <div className={styles.noteSection}>
          <label className={styles.noteLabel}>
            <i className="fas fa-sticky-note"></i> Ghi chú
          </label>
          <textarea
            className={styles.noteTextarea}
            placeholder="Thêm ghi chú về tiến độ (tuỳ chọn)..."
            value={note}
            onChange={(e) => onNoteChange?.(e.target.value)}
            disabled={isUpdating}
            rows={3}
          />
        </div>

        {/* Bottom action buttons — only rendered when used standalone (not in slideout) */}
        {(onUpdate || onCancel) && (
          <div className={styles.actions}>
            {onCancel && (
              <Button
                variant="secondary"
                size="md"
                onClick={onCancel}
                disabled={isUpdating}
              >
                Hủy
              </Button>
            )}
            {onUpdate && (
              <Button
                variant="primary"
                size="md"
                onClick={onUpdate}
                disabled={isUpdating}
                className={styles.updateBtn}
              >
                {isUpdating ? (
                  <><i className="fas fa-spinner fa-spin"></i> Đang cập nhật...</>
                ) : (
                  <><i className="fas fa-check"></i> Cập nhật</>
                )}
              </Button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};
