import React, { useEffect, useState } from 'react';
import Parcel from 'single-spa-react/parcel';
import { navigateToUrl } from 'single-spa';
import type { ParcelConfigObject } from 'single-spa';

declare const System: { import: (name: string) => Promise<any> };

export const NotificationCenterSlot: React.FC = () => {
  const [parcelConfig, setParcelConfig] = useState<ParcelConfigObject | null>(null);

  useEffect(() => {
    System.import('@linm/notification')
      .then((m) => {
        if (m?.NotificationCenterParcel) setParcelConfig(m.NotificationCenterParcel);
      })
      .catch(() => {});
  }, []);

  if (!parcelConfig) return null;

  return (
    <Parcel
      config={parcelConfig}
      wrapWith="div"
      onNavigate={navigateToUrl}
    />
  );
};
