/**
 * Task service facade.
 */

import { TaskFilters } from '../../models/Task';
import { UUID } from '../../models/common';
import { taskEndpoint } from './endpoint';
import {
  CreateTaskRequest, UpdateTaskRequest,
  RequestSupportRequest, AssignCollaboratorRequest,
  RequestReassignmentRequest, ApproveReassignmentRequest,
  MarkBlockedRequest, ApproveTaskRequest,
  RequestChangesRequest, CancelTaskRequest,
} from './requestModel';

export const taskService = {
  getTasks: (filters?: TaskFilters, page = 1, pageSize = 20) =>
    taskEndpoint.getTasks(filters, page, pageSize),

  getPoolTasks: (skills?: string[]) => taskEndpoint.getPoolTasks(skills),

  getPoolStats: () => taskEndpoint.getPoolStats(),

  getStats: () => taskEndpoint.getStats(),

  getTaskById: (id: string) => taskEndpoint.getTaskById(id),

  createTask: (data: CreateTaskRequest) => taskEndpoint.createTask(data),

  updateTask: (id: string, data: UpdateTaskRequest) => taskEndpoint.updateTask(id, data),

  claimTask: (taskId: string) => taskEndpoint.claimTask(taskId),

  updateTaskStatus: (taskId: UUID, status: string) =>
    taskEndpoint.updateTaskStatus(taskId, status),

  updateProgress: (taskId: string, progress: number, note?: string) =>
    taskEndpoint.updateProgress(taskId, progress, note),

  submitForReview: (taskId: string) => taskEndpoint.submitForReview(taskId),

  completeTask: (taskId: string) => taskEndpoint.completeTask(taskId),

  requestSupport: (taskId: string, req: RequestSupportRequest) =>
    taskEndpoint.requestSupport(taskId, req),

  assignCollaborator: (taskId: string, req: AssignCollaboratorRequest) =>
    taskEndpoint.assignCollaborator(taskId, req),

  requestReassignment: (taskId: string, req: RequestReassignmentRequest) =>
    taskEndpoint.requestReassignment(taskId, req),

  approveReassignment: (taskId: string, req: ApproveReassignmentRequest) =>
    taskEndpoint.approveReassignment(taskId, req),

  markBlocked: (taskId: string, req: MarkBlockedRequest) =>
    taskEndpoint.markBlocked(taskId, req),

  unblockTask: (taskId: string) => taskEndpoint.unblockTask(taskId),

  approveTask: (taskId: string, req: ApproveTaskRequest) =>
    taskEndpoint.approveTask(taskId, req),

  requestChanges: (taskId: string, req: RequestChangesRequest) =>
    taskEndpoint.requestChanges(taskId, req),

  cancelTask: (taskId: string, req: CancelTaskRequest) =>
    taskEndpoint.cancelTask(taskId, req),

  startTask: (taskId: string) => taskEndpoint.startTask(taskId),

  getDepartmentTasks: (departmentId: UUID) =>
    taskEndpoint.getDepartmentTasks(departmentId),

  claimDepartmentTask: (taskId: UUID) => taskEndpoint.claimDepartmentTask(taskId),
};
