px;\n  background: var(--ds-color-primary, #2563eb);\n  color: white;\n  border: none;\n  border-radius: 8px;\n  font-weight: 600;\n  font-size: 14px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  transition: var(--transition);\n}\n\n.modalBtnPrimary:hover {\n  background: var(--ds-color-primary, #2563eb);\n}\n\n.modalBtnSecondary {\n  padding: 10px 22px;\n  background: white;\n  color: var(--ds-color-text-secondary, #4A4A4A);\n  border: 1.5px solid var(--ds-color-border, #BABCBE);\n  border-radius: 8px;\n  font-weight: 500;\n  font-size: 14px;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.modalBtnSecondary:hover {\n  background: var(--ds-color-bg-subtle, #F6F6F6);\n  border-color: var(--ds-color-text-placeholder, #B2B2B2);\n}\n\n/* Checklist Container */\n.checklist {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n/* Checklist Item */\n.checklistItem {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 12px;\n  background: var(--ds-color-bg-subtle, #F6F6F6);\n  border-radius: 8px;\n  transition: var(--transition);\n  position: relative;\n}\n\n.checklistItem:hover {\n  background: var(--ds-color-bg-subtle, #F6F6F6);\n}\n\n.checklistItem:hover .checklistActions {\n  opacity: 1;\n}\n\n.checklistItem input[type='checkbox'] {\n  width: 20px;\n  height: 20px;\n  cursor: pointer;\n  flex-shrink: 0;\n}\n\n.checklistItem label {\n  flex: 1;\n  cursor: default;\n  word-break: break-word;\n}\n\n/* Completed State */\n.checklistItem.completed {\n  opacity: 0.6;\n}\n\n.checklistItem.completed label {\n  text-decoration: line-through;\n}\n\n/* Editing State */\n.checklistItem.editing {\n  background: white;\n  border: 2px solid var(--ds-color-primary, #2563eb);\n}\n\n/* Checklist Actions */\n.checklistActions {\n  display: flex;\n  gap: 8px;\n  opacity: 0;\n  transition: opacity 0.2s;\n}\n\n.actionIcon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 28px;\n  height: 28px;\n  background: white;\n  border: var(--ds-border, 1px solid #BABCBE);\n  border-radius: 8px;\n  color: var(--ds-color-text-tertiary, #6D6D6D);\n  cursor: pointer;\n  transition: var(--transition);\n  padding: 0;\n}\n\n.actionIcon:hover {\n  background: var(--ds-color-primary, #2563eb);\n  border-color: var(--ds-color-primary, #2563eb);\n  color: white;\n}\n\n.actionIcon:last-child:hover {\n  background: var(--ds-color-error, #C33A00);\n  border-color: var(--ds-color-error, #C33A00);\n}\n\n.actionIcon:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n/* Edit Input */\n.editInput {\n  flex: 1;\n  padding: 8px;\n  border: 1px solid var(--ds-color-primary, #2563eb);\n  border-radius: 8px;\n  font-size: var(--ds-font-size-input-desktop, 14px);\n}\n\n.editInput:focus {\n  outline: none;\n  box-shadow: var(--ds-focus-shadow, 0px 0px 4px #BABCBE);\n}\n\n/* Edit Actions */\n.editActions {\n  display: flex;\n  gap: 8px;\n}\n\n.saveBtn,\n.cancelBtn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 32px;\n  height: 32px;\n  border: none;\n  border-radius: 8px;\n  cursor: pointer;\n  transition: var(--transition);\n  padding: 0;\n}\n\n.saveBtn {\n  background: var(--ds-color-success, #0D8240);\n  color: white;\n}\n\n.saveBtn:hover:not(:disabled) {\n  background: var(--ds-color-success, #0D8240);\n}\n\n.cancelBtn {\n  background: var(--ds-color-border, #BABCBE);\n  color: var(--ds-color-text-secondary, #4A4A4A);\n}\n\n.cancelBtn:hover:not(:disabled) {\n  background: var(--ds-color-text-placeholder, #B2B2B2);\n}\n\n.saveBtn:disabled,\n.cancelBtn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n/* Empty Checklist */\n.emptyChecklist {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  padding: 32px 16px;\n  color: var(--ds-color-text-placeholder, #B2B2B2);\n  text-align: center;\n}\n\n.emptyChecklist i {\n  font-size: 32px;\n  color: var(--ds-color-border, #BABCBE);\n}\n\n.emptyChecklist p {\n  margin: 0;\n  font-size: var(--ds-font-size-input-desktop, 14px);\n}\n\n/* Add Subtask Form */\n.addSubtask {\n  display: flex;\n  gap: 12px;\n  padding: 12px;\n  background: white;\n  border: 2px dashed var(--ds-color-border, #BABCBE);\n  border-radius: 8px;\n  margin-top: 4px;\n  transition: var(--transition);\n}\n\n.addSubtask:hover {\n  border-color: var(--ds-color-primary, #2563eb);\n  background: var(--ds-color-bg-subtle, #F6F6F6);\n}\n\n.newSubtaskInput {\n  flex: 1;\n  padding: 8px 12px;\n  border: var(--ds-border, 1px solid #BABCBE);\n  border-radius: 8px;\n  font-size: var(--ds-font-size-input-desktop, 14px);\n  transition: var(--transition);\n}\n\n.newSubtaskInput:focus {\n  outline: none;\n  border-color: var(--ds-color-primary, #2563eb);\n  box-shadow: var(--ds-focus-shadow, 0px 0px 4px #BABCBE);\n}\n\n.newSubtaskInput:disabled {\n  background-color: var(--ds-color-bg-subtle, #F6F6F6);\n  cursor: not-allowed;\n}\n\n/* Responsive Design */\n\n/* Tablet: 641px - 1024px */\n@media (max-width: 1024px) {\n  .checklistActions {\n    opacity: 1;\n  }\n}\n\n/* Mobile: <641px */\n@media (max-width: 640px) {\n  .cardBody {\n    padding: 16px;\n  }\n\n  .checklistHeader {\n    flex-direction: column;\n    align-items: flex-start;\n    gap: 8px;\n  }\n\n  .checklistItem {\n    flex-wrap: wrap;\n    padding: 10px;\n    gap: 8px;\n  }\n\n  .checklistItem input[type='checkbox'] {\n    width: 18px;\n    height: 18px;\n  }\n\n  .checklistItem label {\n    font-size: var(--ds-font-size-input-desktop, 14px);\n  }\n\n  .checklistActions {\n    opacity: 1;\n    gap: 6px;\n  }\n\n  .actionIcon {\n    width: 26px;\n    height: 26px;\n    font-size: var(--ds-font-size-small, 12px);\n  }\n\n  .editInput {\n    font-size: var(--ds-font-size-input-desktop, 14px);\n    padding: 6px 8px;\n  }\n\n  .editActions {\n    width: 100%;\n    justify-content: flex-end;\n    gap: 6px;\n  }\n\n  .saveBtn,\n  .cancelBtn {\n    width: 30px;\n    height: 30px;\n    font-size: var(--ds-font-size-small, 12px);\n  }\n\n  .addSubtask {\n    flex-direction: column;\n    gap: 8px;\n    padding: 10px;\n  }\n\n  .newSubtaskInput {\n    font-size: var(--ds-font-size-input-desktop, 14px);\n  }\n\n  .emptyChecklist {\n    padding: 24px 16px;\n  }\n\n  .emptyChecklist i {\n    font-size: 22px;\n  }\n\n  .emptyChecklist p {\n    font-size: var(--ds-font-size-input-desktop, 14px);\n  }\n}\n"],"sourceRoot":""}]);
